/**
 * Signed-transaction vectors, and how they were produced.
 *
 * Both were built by a throwaway RLP *encoder* over the real calldata from
 * `mobile-agent/signer/abi.ts` (`encodeClaimHumanQuota`, `encodeCreateMemeToken`) and then inlined here as
 * literals. The gateway deliberately ships a decoder only - an encoder in production code would be a way to
 * fabricate a transaction the gateway would then agree with - so the vectors cannot be regenerated by the
 * code under test, which is the point: they are independent evidence.
 *
 * The `r`/`s` bytes are placeholders (`0x11..`, `0x22..`). Nothing in this build recovers a signature or
 * re-derives a hash (see `tx.ts`), and `broadcast.test.ts` asserts that `signerRecovery` stays
 * `"unavailable"`, so a placeholder is honest rather than convenient.
 *
 * The first draft of the encoder emitted `0x81 0x09` for the nonce, which `rlp.ts` refused as a non-canonical
 * single-byte string. That refusal is now a test (`tx.test.ts`), so the vectors carry a little of their own
 * provenance.
 */

/** `HumanToken` in the local deployment manifest. */
export const HUMAN_TOKEN = "0xcf7ed3acca5a467e9e704c703e8d87f634fb0fc9";

/** `MaoTangFactory` in the local deployment manifest. */
export const FACTORY = "0x5fbdb2315678afecb367f032d93f642f64180aa3";

/** The owner account the C-end panel reads. */
export const OWNER = "0x70997970c51812dc3a010c7d01b50e0d17dc79c8";

/** A destination no manifest declares, for the `DESTINATION_NOT_ALLOWED` branch. */
export const STRANGER = "0x3535353535353535353535353535353535353535";

export const LOCAL_CHAIN_ID = 31337;

/** `HumanToken.claimHumanQuota(bytes,bytes32)` calldata with a 256-byte proof and a canonical nullifier. */
export const CLAIM_CALLDATA =
  "";

/** `MaoTangFactory.createMemeToken(string,string)` calldata for `("Mao Tang", "MAOTANG")`. */
export const CREATE_CALLDATA =
  "";

/** The nullifier `CLAIM_CALLDATA` carries: 32 bytes, below the BN254 scalar field, non-zero. */
export const NULLIFIER = "0x0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d01";

/** A second, distinct canonical nullifier: the same device one epoch later. */
export const NULLIFIER_B = "0x0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d02";

/**
 * A legacy (type 0) EIP-155 transaction: chain 31337, nonce 9, 20 gwei, 21000 gas, no value, `to` the
 * `HumanToken`, calldata `CLAIM_CALLDATA`, `v = 31337 * 2 + 35 = 62709`.
 */
export const LEGACY_CLAIM_TRANSACTION =
  "";

/**
 * An EIP-1559 (type 2) transaction: chain 31337, nonce 7, `to` the factory, no value, calldata
 * `CREATE_CALLDATA`, empty access list.
 */
export const TYPED_CREATE_TRANSACTION =
  "";

/** The `v` of an EIP-155 legacy transaction on chain `chainId` with `yParity` 0 or 1. */
export function legacyV(chainId: number, yParity: 0 | 1 = 0): bigint {
  return BigInt(chainId) * 2n + 35n + BigInt(yParity);
}